import { useState, useEffect } from 'react';
import { stores, products, categories, banners } from './data';
import type { Product } from './data';
import ProductCard from './ProductCard';

type Props = {
  query: string;
    setQuery: (v: string) => void;
      category: string;
        setCategory: (v: string) => void;
          onlyOffers: boolean;
            setOnlyOffers: (v: boolean) => void;
              favs: number[];
                onToggleFav: (id: number) => void;
                  onOpenProduct: (id: number) => void;
                    onOpenStore: (id: number) => void;
                      available: boolean;
                        govName: string;
                          onPickGov: () => void;
                          };

                          function Home(props: Props) {
                            const {
                                query, setQuery, category, setCategory, onlyOffers, setOnlyOffers,
                                    favs, onToggleFav, onOpenProduct, onOpenStore, available, govName, onPickGov
                                      } = props;

                                        const [bannerIdx, setBannerIdx] = useState(0);
                                          const [showSug, setShowSug] = useState(false);
                                            const [minPrice, setMinPrice] = useState("");
                                              const [maxPrice, setMaxPrice] = useState("");
                                                const [sort, setSort] = useState("none");

                                                  useEffect(() => {
                                                      const t = setInterval(() => setBannerIdx((i) => (i + 1) % banners.length), 4500);
                                                          return () => clearInterval(t);
                                                            }, []);

                                                              function storeName(id: number) {
                                                                  const s = stores.find((x) => x.id === id);
                                                                      return s ? s.name : "";
                                                                        }

                                                                          function clearAll() {
                                                                              setQuery("");
                                                                                  setCategory("");
                                                                                      setOnlyOffers(false);
                                                                                          setMinPrice("");
                                                                                              setMaxPrice("");
                                                                                                  setSort("none");
                                                                                                      setShowSug(false);
                                                                                                        }

                                                                                                          function nextSort() {
                                                                                                              if (sort === "none") setSort("asc");
                                                                                                                  else if (sort === "asc") setSort("desc");
                                                                                                                      else setSort("none");
                                                                                                                        }

                                                                                                                          function renderCard(p: Product) {
                                                                                                                              return (
                                                                                                                                    <ProductCard
                                                                                                                                            key={p.id}
                                                                                                                                                    product={p}
                                                                                                                                                            isFav={favs.includes(p.id)}
                                                                                                                                                                    onToggleFav={() => onToggleFav(p.id)}
                                                                                                                                                                            onOpen={() => onOpenProduct(p.id)}
                                                                                                                                                                                  />
                                                                                                                                                                                      );
                                                                                                                                                                                        }

                                                                                                                                                                                          const q = query.trim();
                                                                                                                                                                                            const searching = q !== "" || category !== "" || onlyOffers;

                                                                                                                                                                                              let results = products.filter((p) => {
                                                                                                                                                                                                  const matchQ =
                                                                                                                                                                                                        q === "" ||
                                                                                                                                                                                                              p.name.includes(q) ||
                                                                                                                                                                                                                    p.category.includes(q) ||
                                                                                                                                                                                                                          p.desc.includes(q) ||
                                                                                                                                                                                                                                storeName(p.storeId).includes(q);
                                                                                                                                                                                                                                    const matchCat = category === "" || p.category === category;
                                                                                                                                                                                                                                        const matchOffer = !onlyOffers || p.oldPrice > p.price;
                                                                                                                                                                                                                                            const matchMin = minPrice === "" || p.price >= Number(minPrice);
                                                                                                                                                                                                                                                const matchMax = maxPrice === "" || p.price <= Number(maxPrice);
                                                                                                                                                                                                                                                    return matchQ && matchCat && matchOffer && matchMin && matchMax;
                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                        if (sort === "asc") results = [...results].sort((a, b) => a.price - b.price);
                                                                                                                                                                                                                                                          else if (sort === "desc") results = [...results].sort((a, b) => b.price - a.price);

                                                                                                                                                                                                                                                            const sortLabel = sort === "asc" ? "⬆ الأرخص" : sort === "desc" ? "⬇ الأغلى" : "↕ ترتيب";

                                                                                                                                                                                                                                                              const sugs: string[] = [];
                                                                                                                                                                                                                                                                if (q !== "") {
                                                                                                                                                                                                                                                                    products.forEach((p) => { if (p.name.includes(q) && !sugs.includes(p.name)) sugs.push(p.name); });
                                                                                                                                                                                                                                                                        stores.forEach((s) => { if (s.name.includes(q) && !sugs.includes(s.name)) sugs.push(s.name); });
                                                                                                                                                                                                                                                                            categories.forEach((c) => { if (c.name.includes(q) && !sugs.includes(c.name)) sugs.push(c.name); });
                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                const topSugs = sugs.slice(0, 5);

                                                                                                                                                                                                                                                                                  if (!available) {
                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                            <div className="soonbox">
                                                                                                                                                                                                                                                                                                    <div className="soonicon">📍</div>
                                                                                                                                                                                                                                                                                                            <h3>STYLEK هيوصل {govName} قريبًا</h3>
                                                                                                                                                                                                                                                                                                                    <p>حاليًا الخدمة متاحة في كفر الشيخ فقط، وهنضيف باقي المحافظات قريبًا.</p>
                                                                                                                                                                                                                                                                                                                            <button onClick={onPickGov}>غيّر المحافظة</button>
                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                          const searchBox = (
                                                                                                                                                                                                                                                                                                                                              <div className="searchwrap">
                                                                                                                                                                                                                                                                                                                                                    <div className="search">
                                                                                                                                                                                                                                                                                                                                                            <input
                                                                                                                                                                                                                                                                                                                                                                      type="text"
                                                                                                                                                                                                                                                                                                                                                                                placeholder="بتدور على إيه؟"
                                                                                                                                                                                                                                                                                                                                                                                          value={query}
                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => { setQuery(e.target.value); setShowSug(true); }}
                                                                                                                                                                                                                                                                                                                                                                                                              onKeyDown={(e) => { if (e.key === "Enter") setShowSug(false); }}
                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                              {query !== "" ? <button className="clearx" onClick={clearAll}>✕</button> : <span>🔍</span>}
                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                          {showSug && topSugs.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="sug">
                                                                                                                                                                                                                                                                                                                                                                                                                                                            {topSugs.map((s) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button key={s} onClick={() => { setQuery(s); setShowSug(false); }}>🔍 {s}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (searching) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const emptyMsg =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  category !== "" && q === "" && !onlyOffers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? "لسه مفيش منتجات في قسم " + category
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : "ملقيناش منتجات مطابقة لبحثك";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {searchBox}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="chipsrow">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {category !== "" && <button className="fchip" onClick={() => setCategory("")}>{category} ✕</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {onlyOffers && <button className="fchip" onClick={() => setOnlyOffers(false)}>العروض ✕</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="filters">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input type="number" placeholder="من سعر" value={minPrice} onChange={(e) => setMinPrice(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input type="number" placeholder="إلى سعر" value={maxPrice} onChange={(e) => setMaxPrice(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button onClick={nextSort}>{sortLabel}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="sec-head"><h3>النتائج ({results.length})</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {results.length > 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="cards">{results.map(renderCard)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="emptybox">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="emptyicon">🔎</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>{emptyMsg}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button onClick={clearAll}>مسح البحث</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const offers = products.filter((p) => p.oldPrice > p.price);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const offerIds = offers.map((p) => p.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const byDate = [...products].sort((a, b) => b.addedAt.localeCompare(a.addedAt));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const fresh = byDate.filter((p) => !offerIds.includes(p.id));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const newList = (fresh.length > 0 ? fresh : byDate).slice(0, 6);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const trending = products
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .filter((p) => (p.views ?? 0) > 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .sort((a, b) => (b.views ?? 0) - (a.views ?? 0))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .slice(0, 4);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function bannerAction(target: string) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (target === "offers") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setOnlyOffers(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const el = document.getElementById("new-section");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (el) el.scrollIntoView({ behavior: "smooth" });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const b = banners[bannerIdx];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {searchBox}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="banner">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h2>{b.title}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p>{b.subtitle}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onClick={() => bannerAction(b.target)}>{b.button}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="dots">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {banners.map((x, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span key={x.id} className={"dotb" + (i === bannerIdx ? " on" : "")} onClick={() => setBannerIdx(i)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="sec-head"><h3>تسوق حسب القسم</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="catgrid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {categories.map((c) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button key={c.name} className="catbox" onClick={() => setCategory(c.name)}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <span>{c.icon}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {c.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {offers.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="sec-head rowhead">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h3>عروض تستاهل</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button className="seeall" onClick={() => setOnlyOffers(true)}>عرض الكل</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="hrow">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {offers.map((p) => <div className="hcard" key={p.id}>{renderCard(p)}</div>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="sec-head" id="new-section"><h3>وصل حديثًا</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="cards">{newList.map(renderCard)}</div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {trending.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="sec-head"><h3>الأكثر رواجًا</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="cards">{trending.map(renderCard)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="sec-head"><h3>اكتشف محلات قريبة منك</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="storelist">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {stores.map((s) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="storecard" key={s.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="logo-circle">{s.icon}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="sinfo">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <strong>{s.name}</strong> {s.verified && <span className="verified">✔ موثق</span>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="smeta">📍 {s.area} | ⭐ {s.rating}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={() => onOpenStore(s.id)}>زيارة المحل</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="soon">المحلات والمنتجات المعروضة تجريبية حاليًا، وهتتبدل ببيانات المحلات الحقيقية.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export default Home;